function scenarioOptions(screen){
  const base=[['normal','Bình thường']];
  if(['catalog','library','books','queue','materials','contributions'].includes(screen))base.push(['loading','Đang tải'],['empty','Không có kết quả'],['error','Lỗi kết nối']);
  if(['detail','reader','library'].includes(screen))base.push(['hidden','Tài liệu bị ẩn']);
  if(['detail','reader'].includes(screen))base.push(['readonly','Không được tải']);
  if(screen==='reader')base.push(['noteerror','Lỗi lưu ghi chú']);
  if(['editor','review'].includes(screen))base.push(['checking','File đang kiểm tra'],['failed','File kiểm tra lỗi']);
  if(screen==='submission')base.push(['changes','Yêu cầu sửa'],['rejected','Từ chối']);
  return base;
}
function navHTML(screen){
  const common=[['catalog','Kho học liệu','search'],['library','Thư viện cá nhân','bookmark'],['books','Danh mục sách','book']];
  const special=state.role==='admin'?[['queue','Duyệt tài liệu','shield'],['management','Học liệu & bàn giao','folder'],['reports','Báo cáo nội dung','flag'],['accounts','Tài khoản','users'],['courses','Danh mục & phân công','list'],['bookadmin','Quản lý sách','book']]:state.role==='lecturer'?[['materials','Giáo trình của tôi','folder']]:[['contributions','Tài liệu đóng góp','upload']];
  const active=screen==='detail'||screen==='reader'?'catalog':screen==='book'?'books':screen==='review'?'queue':screen==='editor'||screen==='submission'?(state.role==='lecturer'?'materials':'contributions'):screen;
  const navItem=([key,name,ico])=>`<a href="#/${key}" ${key===active?'aria-current="page"':''}>${icon(ico)}<span>${name}</span>${key==='queue'?`<span class="count">${requests.filter(r=>r.status==='SUBMITTED').length}</span>`:''}</a>`;
  return `<aside class="sidebar" id="sidebar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Đóng điều hướng">${icon('close')}</button>${brand()}<nav aria-label="Điều hướng chính"><div class="nav">${common.map(navItem).join('')}</div><p class="nav-section-title">${state.role==='admin'?'Quản trị':state.role==='lecturer'?'Không gian giảng viên':'Đóng góp'}</p><div class="nav">${special.map(navItem).join('')}</div></nav><div class="sidebar-bottom"><div class="profile"><span class="avatar">${people[state.role][0]}</span><div><strong>${people[state.role][1]}</strong><small>${roleNames[state.role]}</small></div></div><a href="#/login">Đăng xuất</a></div></aside>`;
}
function listState(){
  if(state.scenario==='loading')return `<div class="loading-rows" role="status"><p>Đang tải dữ liệu…</p>${[1,2,3].map(()=>'<div class="skeleton wide"></div><div class="skeleton"></div><hr class="quiet-rule">').join('')}</div>`;
  if(state.scenario==='error')return empty('Không tải được dữ liệu','Kết nối đang gián đoạn. Bạn có thể thử lại; bộ lọc hiện tại được giữ.',btn('Thử lại','retry','','refresh'),'refresh');
  if(state.scenario==='empty')return empty('Chưa có kết quả phù hợp','Thử bỏ bớt bộ lọc hoặc tìm bằng tên môn học.',btn('Xóa bộ lọc','clear-filters','','refresh'),'search');
  return '';
}
function empty(title,text,action='',ico='folder'){return `<div class="empty">${icon(ico)}<h2>${title}</h2><p>${text}</p>${action}</div>`;}
function documentRow(d){
  return `<article class="document-row"><div class="study-cover tone-${(d.id-1)%4+1}" aria-hidden="true"><small>HUCEScholar</small><strong>${esc(d.course)}</strong><span>${d.kind==='student'?'TÀI LIỆU BỔ SUNG':'HỌC LIỆU'}<br>Bìa minh họa · v${d.version}</span></div><div><div class="row-tags">${badge(d.kind==='lecturer'?'Giáo trình giảng viên':'Sinh viên bổ sung',d.kind==='student'?'warning':'')}${badge(`Phiên bản ${d.version}`,'neutral')}</div><h3><a href="#/detail/${d.id}">${esc(d.title)}</a></h3><div class="row-meta"><span>${esc(d.course)}</span><span>${esc(d.author)}</span><span>${d.download?'Được tải file gốc':'Chỉ đọc trực tuyến'}</span></div></div><div class="document-actions">${link('Xem tài liệu',`detail/${d.id}`,'secondary','arrow')}<button class="icon-button" data-action="save:${d.id}" aria-label="${saved[state.role].has(d.id)?'Bỏ lưu':'Lưu'} ${esc(d.title)}" aria-pressed="${saved[state.role].has(d.id)}">${icon('bookmark')}</button></div></article>`;
}
function catalog(){
  const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');
  const found=documents.filter(d=>d.published&&d.visibility==='VISIBLE'&&normalize(`${d.title} ${d.course} ${d.author}`).includes(normalize(state.query))&&(!state.course||d.course===state.course)&&(!state.source||d.kind===state.source));
  const resumeEntry=Object.entries(progress[state.role]).reverse().find(([key])=>{const d=documents.find(x=>x.id===Number(key.split('/')[0]));return d&&d.published&&d.visibility==='VISIBLE';});
  const resumeDoc=resumeEntry?documents.find(d=>d.id===Number(resumeEntry[0].split('/')[0])):null;
  const resumeVersion=resumeEntry?Number(resumeEntry[0].split('/')[1]):0;
  const resumeBlock=resumeDoc?`<aside class="continue-reading" aria-label="Tiếp tục đọc"><h2>${icon('bookmark')}Tiếp tục đọc</h2><h3>${esc(resumeDoc.course)}</h3><p>Trang ${resumeEntry[1]} / ${resumeDoc.pages} · Phiên bản ${resumeVersion}</p><a href="#/reader/${resumeDoc.id}/${resumeVersion}/${resumeEntry[1]}">Mở trang đang đọc ${icon('arrow')}</a></aside>`:`<aside class="continue-reading"><h2>${icon('bookmark')}Góc học tập của bạn</h2><h3>Tài liệu đã lưu, luôn dễ tìm.</h3><p>Mở lại tài liệu và ghi chú trong thư viện cá nhân.</p><a href="#/library">Vào thư viện cá nhân ${icon('arrow')}</a></aside>`;
  return `<section class="catalog-intro"><div><h1>Tri thức xây nền.<span>Học tập vươn xa.</span></h1><p>Tìm giáo trình, khám phá học liệu theo môn và giữ lại những điều cần nhớ trong không gian học tập của bạn.</p></div>${resumeBlock}</section>`+`<form id="search-form" class="search-panel"><div class="search-row"><div class="search-box"><label for="search">Tìm trong kho học liệu</label>${icon('search')}<input id="search" name="query" value="${esc(state.query)}" placeholder="Ví dụ: cơ học kết cấu" type="search"></div><button class="button" type="submit">Tìm tài liệu</button></div><div class="filters"><div class="filter"><label for="filter-course">Môn học</label><select id="filter-course"><option value="">Tất cả môn học</option>${options(courseNames,state.course)}</select></div><div class="filter"><label for="filter-source">Nguồn học liệu</label><select id="filter-source"><option value="">Tất cả nguồn</option value="lecturer" ${state.source==='lecturer'?'selected':''}>Giáo trình giảng viên</option><option value="student" ${state.source==='student'?'selected':''}>Sinh viên bổ sung</option></select></div><button type="button" class="text-button" data-action="clear-filters">Xóa bộ lọc</button></div></form><div class="results-bar"><h2>${state.query?'Kết quả tìm kiếm':'Học liệu đã công bố'}</h2><span>${found.length} tài liệu trong bộ dữ liệu minh họa</span></div>${listState() || (found.length?`<div class="document-list">${found.map(documentRow).join('')}</div>`:empty('Không tìm thấy tài liệu','Không có kết quả cho truy vấn và bộ lọc hiện tại.',btn('Xóa bộ lọc','clear-filters'),'search'))}`;
}
function detail(id){
  const d=docById(id),blocked=state.scenario==='hidden'||d.visibility==='HIDDEN',canDownload=d.download&&state.scenario!=='readonly';
  return back('Về kho học liệu','catalog')+`<div class="detail-layout"><div><section class="panel"><div class="row-tags">${badge(d.kind==='lecturer'?'Giáo trình giảng viên':'Sinh viên bổ sung',d.kind==='student'?'warning':'')}${statusBadge('APPROVED')}</div><h1 class="detail-title">${esc(d.title)}</h1><p class="muted">${esc(d.author)} · ${esc(d.course)}</p>${blocked?notice('Tài liệu đang được ẩn. Bạn chưa thể đọc hoặc tải. Mục lưu và ghi chú trước đó vẫn được giữ.','warning'):''}<p class="detail-summary">${esc(d.description)}</p><dl class="metadata"><dt>Phiên bản hiện hành</dt><dd>${d.version} · Công bố 10/10/2026 (minh họa)</dd><dt>Nguồn</dt><dd>Bộ dữ liệu thiết kế HUCEScholar — chưa phải tài liệu trường</dd><dt>Quyền sử dụng</dt><dd>${canDownload?'Đọc trực tuyến và tải file gốc trong tình huống mẫu':'Chỉ đọc trực tuyến trong tình huống mẫu'}</dd><dt>Định dạng</dt><dd>PDF · ${d.pages} trang minh họa</dd><dt>Người phụ trách</dt><dd>${esc(d.manager)}</dd></dl></section><section class="panel section"><h2>Phiên bản tài liệu</h2><p class="small">Ghi chú thuộc phiên bản bạn đã đọc. Bản mới giữ nguyên ghi chú của bản cũ.</p><ul class="version-list"><li><div><strong>Phiên bản ${d.version} — hiện hành</strong><small>Đã duyệt · 10/10/2026 · dữ liệu mẫu</small></div>${blocked?badge('Không khả dụng','warning'):link('Đọc bản này',`reader/${d.id}/${d.version}`,'secondary')}</li>${d.id===1?`<li><div><strong>Phiên bản 1</strong><small>Bản đã duyệt trước đó · quyền truy cập được kiểm tra riêng</small></div>${blocked?badge('Không khả dụng','warning'):link('Đọc bản 1',`reader/${d.id}/1`,'secondary')}</li>`:''}</ul></section></div><aside class="panel action-panel"><h2>Bắt đầu học</h2>${blocked?'<button class="button" disabled>Hiện chưa thể đọc</button>':link('Đọc trực tuyến',`reader/${d.id}/${d.version}`,'','book')}<button class="button secondary" data-action="save:${d.id}">${icon('bookmark')}${saved[state.role].has(d.id)?'Đã lưu · Bỏ lưu':'Lưu vào thư viện'}</button>${canDownload&&!blocked?btn('Tải file gốc',`download:${d.id}`,'secondary','download'):'<button class="button secondary" disabled>Tải file gốc</button>'}<span class="small">${blocked?'Đọc và tải tạm ngừng trong thời gian tài liệu bị ẩn.':canDownload?'Ghi chú được lưu riêng, không nằm trong file gốc tải về.':'Nguồn chưa cho phép tải file gốc. Bạn có thể đọc trực tuyến.'}</span><hr class="quiet-rule"><button class="text-button" data-action="report:${d.id}">${icon('flag')} Báo cáo vấn đề</button></aside></div>`;
}
function paper(d,page){
  const chapter=page===1?'Tổng quan và cách sử dụng':page===2?'Phương pháp mặt cắt':'Ví dụ và câu hỏi ôn tập';
  return `<div class="paper-running">HUCEScholar · Trang đọc minh họa · Phiên bản ${state.readerVersion}</div><h2>${page}. ${chapter}</h2><p>Trang này minh họa trải nghiệm đọc tài liệu trong HUCEScholar. Tên môn và nội dung được dùng để thiết kế bố cục; đây không phải bản sao giáo trình của nhà trường.</p><h3>${page===2?'Xác định phần kết cấu cần xét':'Đọc có mục tiêu'}</h3><p>${page===2?'<mark>Lựa chọn mặt cắt giúp cô lập phần kết cấu cần xét.</mark> Khi học, hãy ghi lại giả thiết và quy ước trước khi đối chiếu với bài giải.':'Trước khi bắt đầu một chương, xem mục tiêu và các khái niệm sẽ sử dụng. Ghi chú theo trang giúp bạn quay lại đúng ngữ cảnh ở lần học tiếp theo.'}</p><div class="formula">${page===2?'ΣFₓ = 0 &nbsp;&nbsp; ΣFᵧ = 0 &nbsp;&nbsp; ΣM = 0':'Đọc → đối chiếu → ghi chú → ôn lại'}</div><h3>Câu hỏi tự kiểm tra</h3><p>Bạn cần những dữ kiện nào trước khi giải bài? Hãy dùng ô ghi chú để viết lại bằng lời của mình. Khi tài liệu có phiên bản mới, ghi chú này vẫn thuộc trang và phiên bản ban đầu.</p><p>Trong sản phẩm thật, vùng này hiển thị PDF, hỗ trợ điều hướng trang và chọn chữ nếu trang có lớp văn bản. Bản thiết kế hiện tại chỉ thể hiện bố cục và phản hồi thao tác.</p><div class="paper-footer">${esc(d.course)} · Minh họa bố cục, không dùng thay tài liệu học tập · ${page} / ${d.pages}</div>`;
}
function reader(id,version){
  const d=docById(id);state.activeId=d.id;state.readerVersion=Number(version)||d.version;state.page=Math.min(Math.max(state.page,1),d.pages);
  const blocked=state.scenario==='hidden'||d.visibility==='HIDDEN';
  const mine=notes.filter(n=>n.doc===d.id&&n.version===state.readerVersion&&n.role===state.role);
  const canDownload=d.download&&state.scenario!=='readonly';
  if(blocked)return back('Về chi tiết tài liệu',`detail/${d.id}`)+heading('Tài liệu hiện chưa khả dụng')+notice('Tài liệu đang được ẩn. Các lượt đọc và tải mới tạm ngừng. Ghi chú của bạn vẫn được giữ, không bị chuyển sang phiên bản khác.','warning')+empty('Chưa thể mở trang tài liệu','Bạn có thể quay lại thư viện và kiểm tra sau.',link('Về thư viện cá nhân','library'),'lock');
  return `<div class="reader-top"><div>${back('Chi tiết tài liệu',`detail/${d.id}`)}<h1 tabindex="-1">${esc(d.title)}</h1><div class="row-meta"><span>Phiên bản ${state.readerVersion}${state.readerVersion===d.version?' · hiện hành':' · bản trước'}</span><span>${esc(d.author)}</span><span>${canDownload?'Được tải file gốc':'Chỉ đọc trực tuyến'}</span></div></div><div class="reader-controls"><button class="icon-button" data-action="prev-page" aria-label="Trang trước" ${state.page===1?'disabled':''}>${icon('back')}</button><label for="page-number">Trang</label><input type="number" id="page-number" min="1" max="${d.pages}" value="${state.page}" aria-label="Số trang"><span class="small">/ ${d.pages}</span><button class="icon-button" data-action="next-page" aria-label="Trang tiếp" ${state.page===d.pages?'disabled':''}>${icon('arrow')}</button><label class="desktop-label" for="zoom">Thu phóng</label><select id="zoom" aria-label="Thu phóng"><option value="100" ${state.zoom===100?'selected':''}>Vừa trang</option><option value="125" ${state.zoom===125?'selected':''}>125%</option></select>${canDownload?btn('Tải gốc',`download:${d.id}`,'secondary','download'):''}<button class="text-button note-tab-trigger" data-action="focus-notes">Ghi chú ${icon('note')}</button></div></div>${state.readerVersion!==d.version?notice(`Bạn đang đọc bản ${state.readerVersion}. Bản hiện hành là ${d.version}; mở bản mới không di chuyển ghi chú cũ. ${link('Đọc bản mới',`reader/${d.id}/${d.version}`,'secondary compact')}`):''}<div class="reader-layout"><aside class="outline-panel"><h2>Mục lục minh họa</h2>${['Tổng quan và cách sử dụng','Phương pháp mặt cắt','Ví dụ và câu hỏi ôn tập'].map((title,i)=>`<button class="${state.page===i+1?'active':''}" data-action="page:${i+1}" ${state.page===i+1?'aria-current="page"':''}>${i+1}. ${title}</button>`).join('')}</aside><div class="paper-stage"><article class="pdf-paper" style="width:${state.zoom}%;max-width:none" aria-label="Trang ${state.page} minh họa">${paper(d,state.page)}</article></div><aside class="notes-panel"><div class="notes-header"><h2 id="notes-heading" tabindex="-1">Ghi chú của tôi</h2><span class="private-label">${icon('lock')}Riêng tư</span></div><p class="small">Bản ${state.readerVersion} · ${mine.length} ghi chú</p><form id="note-form" class="note-form"><label for="note-content">Thêm ghi chú ở trang ${state.page}</label><textarea id="note-content" name="note" required placeholder="Điều cần nhớ hoặc câu hỏi của bạn…">${esc(state.noteDraft)}</textarea><div class="save-indicator ${state.saveState==='failed'?'error':''}" id="save-indicator" role="status">${state.saveState==='failed'?'Chưa lưu được. Nội dung vẫn được giữ.':state.saveState==='dirty'?'Có thay đổi chưa lưu.':state.saveState==='saved'?'Đã lưu trong phiên xem thử.':'Chỉ bạn xem được ghi chú của mình.'}</div><button class="button" type="submit">${icon(state.saveState==='failed'?'refresh':'plus')}${state.saveState==='failed'?'Thử lưu lại':'Lưu ghi chú'}</button></form>${state.saveState==='failed'?notice('Lỗi kết nối mô phỏng. Nút thử lại sẽ mô phỏng kết nối được khôi phục.','error'):''}<div class="section" style="margin-top:22px">${mine.length?mine.map(n=>`<article class="note-item"><div class="note-page"><button class="reader-page-link" data-action="page:${n.page}">Trang ${n.page} · Bản ${n.version}</button><span>Đã lưu</span></div>${n.quote?`<blockquote>${esc(n.quote)}</blockquote>`:''}<p>${esc(n.content)}</p><button class="text-button" data-action="delete-note:${n.id}">Xóa ghi chú</button></article>`).join(''):'<p class="notes-empty">Chưa có ghi chú cho phiên bản này. Viết ghi chú đầu tiên ở ô phía trên.</p>'}</div></aside></div>`;
}
function library(){
  const ids=[...saved[state.role]],mine=notes.filter(n=>n.role===state.role);
  const cards=ids.map(id=>{const d=docById(id),key=Object.keys(progress[state.role]).find(x=>x.startsWith(`${id}/`)),v=key?Number(key.split('/')[1]):d.version,p=key?progress[state.role][key]:1;return `<article class="document-row"><div class="doc-thumbnail">${icon('bookmark')}</div><div><div class="row-tags">${badge(`Đang đọc bản ${v}`,'neutral')}${state.scenario==='hidden'||d.visibility==='HIDDEN'?badge('Tạm không khả dụng','warning'):badge(`Trang ${p} / ${d.pages}`)}</div><h3>${esc(d.title)}</h3><div class="row-meta"><span>${notes.filter(n=>n.role===state.role&&n.doc===id).length} ghi chú riêng</span><span>${esc(d.course)}</span></div></div><div class="document-actions">${state.scenario==='hidden'||d.visibility==='HIDDEN'?'<button class="button secondary" disabled>Chưa thể đọc</button>':link('Đọc tiếp',`reader/${id}/${v}/${p}`,'','book')}<button class="text-button" data-action="unsave:${id}">Bỏ lưu</button></div></article>`;}).join('');
  return heading('Thư viện cá nhân','Tiếp tục từ nơi bạn dừng lại. Ghi chú giữ nguyên phiên bản, kể cả khi có bản mới.')+`<div class="tabs" role="tablist" aria-label="Nội dung thư viện"><button role="tab" aria-selected="${state.libraryTab==='saved'}" data-action="library-tab:saved">Tài liệu đã lưu (${ids.length})</button><button role="tab" aria-selected="${state.libraryTab==='notes'}" data-action="library-tab:notes">Ghi chú của tôi (${mine.length})</button></div>${state.scenario==='hidden'?notice('Tài liệu tạm ẩn vẫn nằm trong thư viện. Không xóa ghi chú hoặc tiến độ khi tài liệu không khả dụng.','warning'):''}${listState()||(state.libraryTab==='saved'?(ids.length?`<div class="document-list">${cards}</div>`:empty('Thư viện chưa có tài liệu','Lưu một tài liệu từ kho để đọc tiếp thuận tiện hơn.',link('Tìm học liệu','catalog','','search'),'bookmark')):(mine.length?`<div class="document-list">${mine.map(n=>`<article class="document-row"><div class="doc-thumbnail">${icon('note')}</div><div><div class="row-tags">${badge(`Bản ${n.version} · Trang ${n.page}`,'neutral')}</div><h3>${esc(docById(n.doc).title)}</h3><p class="small">${esc(n.content)}</p></div><div class="document-actions">${link('Mở ghi chú',`reader/${n.doc}/${n.version}/${n.page}`,'secondary','arrow')}</div></article>`).join('')}</div>`:empty('Chưa có ghi chú','Ghi chú bạn tạo trong reader sẽ xuất hiện ở đây.',link('Về kho học liệu','catalog'),'note')))}`;
}
function bookCatalog(){return heading('Danh mục sách','Tra thông tin và nguồn sách. Bản ghi thư viện không đồng nghĩa có PDF được phép tải.')+(listState()||`<div class="book-grid">${books.map(b=>`<article class="book-entry"><div class="book-cover"><span>${esc(b.cover).replace(/\n/g,'<br>')}</span><small>Bìa chữ minh họa</small></div><div>${badge('Nguồn ngoài','blue')}<h2>${esc(b.title)}</h2><p>${esc(b.author)} · ${esc(b.year)}<br>${esc(b.edition)}</p>${link('Xem thông tin',`book/${b.id}`,'secondary','arrow')}</div></article>`).join('')}</div>`);}
function bookDetail(id){const b=books.find(x=>x.id===Number(id))||books[0];return back('Về danh mục sách','books')+`<div class="detail-layout"><section class="panel"><div class="row-tags">${badge('Bản ghi sách nguồn ngoài','blue')}</div><h1 class="detail-title">${esc(b.title)}</h1><p class="muted">${esc(b.author)}</p><dl class="metadata"><dt>Năm xuất bản</dt><dd>${esc(b.year)} — minh họa</dd><dt>Ấn bản</dt><dd>${esc(b.edition)}</dd><dt>ISBN</dt><dd>Chưa cung cấp trong dữ liệu thiết kế</dd><dt>Môn liên quan</dt><dd>${esc(b.course)}</dd><dt>Nguồn danh mục</dt><dd>Nguồn minh họa cho prototype, chưa nhập dữ liệu trường</dd><dt>Kiểm tra nguồn</dt><dd>Cần kiểm tra quyền và URL thực tế trước triển khai</dd></dl>${notice('Chưa có PDF nội bộ được cấp quyền cho bản ghi này. Quyền đọc tại website nguồn do đơn vị nguồn quyết định.')}</section><aside class="panel action-panel"><h2>Truy cập nguồn</h2>${btn('Xem nguồn sách',`book-source:${b.id}`,'','external')}<p class="small">Mở tại đơn vị cung cấp. HUCEScholar không tự cấp quyền hoặc mật khẩu cho website nguồn.</p><hr class="quiet-rule"><button class="text-button" data-action="report-book:${b.id}">Báo cáo liên kết hoặc thông tin sai</button></aside></div>`;}
function materials(){
  const isLecturer=state.role==='lecturer',mine=requests.filter(r=>r.role===(isLecturer?'lecturer':'student')&&docById(r.doc).manager===people[state.role][1]);
  return heading(isLecturer?'Giáo trình của tôi':'Tài liệu đóng góp',isLecturer?'Biên soạn trong phạm vi môn được phân công. Mọi phiên bản mới đều cần được duyệt.':'Chia sẻ tài liệu bổ sung. Bài gửi được tách nhãn khỏi giáo trình giảng viên.',link(isLecturer?'Tạo giáo trình':'Gửi tài liệu bổ sung','editor/new','','plus'))+(listState()||`<div class="table-wrap"><table><caption>Danh sách tài liệu của tôi</caption><thead><tr><th>Tài liệu / môn</th><th>Bản công bố</th><th>Bản đang làm</th><th>Thao tác</th></tr></thead><tbody>${mine.map(r=>{const d=docById(r.doc);return `<tr><td><strong>${esc(d.title)}</strong><small>${esc(d.course)}</small></td><td>${d.published?badge(`Phiên bản ${d.version}`):'<span class="muted">Chưa công bố</span>'}</td><td>${statusBadge(r.status)}<small>Phiên bản ${r.version}</small></td><td>${link('Xem lần gửi',`submission/${r.id}`,'secondary compact')}</td></tr>`;}).join('')}</tbody></table></div>`)+notice('Duyệt bản mới không ghi đè file hay ghi chú của bản cũ. Tài liệu đã duyệt chỉ được cập nhật bằng phiên bản mới.');
}
function editor(id){
  const existing=id!=='new'?reqById(id):null;
  if(existing&&existing.status==='SUBMITTED')return heading('Bản đang chờ duyệt')+notice('Rút bản về nháp trước khi chỉnh sửa. Không thay đổi nội dung đang chờ quyết định.','warning')+link('Xem lần gửi',`submission/${existing.id}`);
  if(existing&&['APPROVED','REJECTED'].includes(existing.status))return heading('Phiên bản đã kết thúc')+notice('Phiên bản đã duyệt hoặc bị từ chối được giữ nguyên. Hãy tạo phiên bản mới.')+btn('Tạo phiên bản mới',`new-version:${existing.id}`,'','plus');
  const d=existing?docById(existing.doc):null;const draft=state.editorDraft || existing?.draft || {};
  const fileBlocked=['checking','failed'].includes(state.scenario);
  return back(state.role==='lecturer'?'Về giáo trình của tôi':'Về tài liệu đóng góp',state.role==='lecturer'?'materials':'contributions')+heading(state.role==='lecturer'?'Soạn giáo trình':'Gửi tài liệu bổ sung','Lưu nháp để hoàn thiện sau, hoặc gửi công bố khi file và nguồn sử dụng đã đủ điều kiện.')+`<div class="detail-layout"><form id="editor-form" class="panel" novalidate data-request="${existing?.id||''}"><div id="form-errors"></div><section class="form-section"><h2>Thông tin học liệu</h2>${field('Tên tài liệu','title',draft.title??d?.title??'','Tên rõ nội dung, tránh chỉ ghi “Tài liệu ôn thi”.','text',true)}<div class="form-grid">${field('Tác giả / người biên soạn','authors',draft.authors??d?.author??people[state.role][1],'Tác giả hiển thị độc lập với người quản lý.','text',true)}<div class="field"><label for="course">Môn học *</label><select id="course" name="course" required><option value="">Chọn môn học</option>${options(state.role==='lecturer'?[courseNames[0],courseNames[4]]:courseNames,draft.course??d?.course??'')}</select><small>${state.role==='lecturer'?'Chỉ hiện môn được phân công; backend cần kiểm tra lại.':'Chọn môn liên quan đến tài liệu.'}</small></div></div>${textarea('Mô tả nội dung','description',draft.description??d?.description??'','Nêu phạm vi, chương hoặc phần bài tập.',true)}${existing?textarea('Thay đổi trong phiên bản này','summary',draft.summary??existing.summary):''}</section><section class="form-section"><h2>File tài liệu</h2><div class="upload-area"><p>${icon('upload')}Chọn PDF để gắn vào bản nháp</p><label for="pdf-file" class="small">File PDF ${existing?'(để trống nếu giữ file mẫu hiện tại)':'*'}</label><input type="file" accept=".pdf,application/pdf" id="pdf-file" name="file"><p class="small" id="file-label">${existing?.fileSelected?esc(existing.file):'Chưa chọn file. Trong prototype chỉ đọc tên file, không upload.'}</p></div>${fileBlocked?notice(state.scenario==='checking'?'File đang được kiểm tra. Chưa thể xem trước hoặc gửi công bố.':'Không thể sử dụng file này. Chọn PDF khác để kiểm tra lại.',state.scenario==='failed'?'error':'warning'):notice(existing?.fileSelected?'File mẫu đã an toàn trong tình huống thiết kế. Thay file sẽ kiểm tra lại.':'File sẽ được kiểm tra trong sản phẩm thật; prototype chỉ mô phỏng trạng thái.')}<div class="row-tags">${badge(state.scenario==='checking'?'CHECKING · Đang kiểm tra':state.scenario==='failed'?'FAILED · Kiểm tra lỗi':existing?.fileSelected?'SAFE · File mẫu an toàn':'Chưa có file',fileBlocked?'warning':'neutral')}</div></section><section class="form-section"><h2>Nguồn và quyền sử dụng</h2>${textarea('Nguồn / tài liệu tham chiếu','source',draft.source??(existing?'Nguồn minh họa đã cung cấp cho bản thiết kế.':''),'Ghi rõ nguồn và bằng chứng có thể kiểm tra.',true)}${textarea('Căn cứ cho phép chia sẻ','rights',draft.rights??(existing?'Căn cứ quyền minh họa; cần thay bằng bằng chứng thực trước triển khai.':''),'Không mặc định tài liệu tìm trên mạng được quyền chia sẻ.',true)}<label class="check-label"><input name="download" type="checkbox" ${draft.download??d?.download?'checked':''}>Cho phép tải file gốc theo quyền nguồn đã xác định</label></section><div class="form-actions">${link('Hủy',state.role==='lecturer'?'materials':'contributions')}<button class="button secondary" type="submit" name="intent" value="draft">Lưu nháp</button><button class="button" type="submit" name="intent" value="submit" ${fileBlocked?'disabled':''}>Gửi công bố</button></div></form><aside class="panel form-side"><h2>Trước khi gửi</h2><ul><li>File PDF đã kiểm tra an toàn.</li><li>Đúng môn học và phạm vi phân công.</li><li>Có nguồn và căn cứ quyền sử dụng.</li><li>Tài liệu chỉ vào kho sau khi admin duyệt.</li></ul><hr class="quiet-rule"><h3>Loại học liệu</h3>${badge(state.role==='lecturer'?'Giáo trình giảng viên':'Sinh viên bổ sung',state.role==='student'?'warning':'')}<p class="small" style="margin-top:12px">${state.role==='student'?'Bạn không chỉnh sửa giáo trình của giảng viên.':'Admin có thể yêu cầu sửa; không sửa nội dung thay giảng viên.'}</p></aside></div>`;
}
function submission(id){const r=reqById(id),d=submittedDoc(r),s=state.scenario==='changes'?'CHANGES_REQUIRED':state.scenario==='rejected'?'REJECTED':r.status;let actions='';
  if(s==='SUBMITTED')actions=btn('Rút về nháp',`withdraw:${r.id}`,'secondary','back');
  if(['DRAFT','CHANGES_REQUIRED'].includes(s))actions=link('Chỉnh sửa bản nháp',`editor/${r.id}`,'','edit');
  if(['APPROVED','REJECTED'].includes(s))actions=btn('Tạo phiên bản mới',`new-version:${r.id}`,'','plus');
  return back('Về tài liệu của tôi',state.role==='lecturer'?'materials':'contributions')+heading('Chi tiết lần gửi','Theo dõi kết quả công bố cho đúng phiên bản.',actions)+`<div class="detail-layout"><section class="panel"><div class="row-tags">${statusBadge(s)}${badge(`Phiên bản ${r.version}`,'neutral')}</div><h2 style="margin-top:20px">${esc(d.title)}</h2><dl class="metadata"><dt>Người gửi</dt><dd>${esc(r.sender)}</dd><dt>Môn học</dt><dd>${esc(d.course)}</dd><dt>Bản đang phục vụ</dt><dd>${d.published?`Phiên bản ${d.version} — giữ nguyên khi bản mới chờ duyệt`:'Chưa có bản công bố'}</dd><dt>Thay đổi</dt><dd>${esc(r.summary)}</dd><dt>Nguồn</dt><dd>${esc(d.source)}</dd><dt>Căn cứ quyền</dt><dd>${esc(d.rights)}</dd><dt>File gửi</dt><dd>${esc(r.file||'Chưa chọn file PDF')}</dd></dl>${['CHANGES_REQUIRED','REJECTED'].includes(s)?notice(`<strong>${s==='REJECTED'?'Lý do từ chối':'Nội dung cần chỉnh sửa'}:</strong> ${esc(r.reason||'Bổ sung nguồn và căn cứ quyền sử dụng cho các hình trong tài liệu.')}`,'warning'):s==='SUBMITTED'?notice('Bản đang chờ duyệt được giữ nguyên. Muốn sửa, bạn cần rút về nháp trước.'):s==='DRAFT'?notice('Bản nháp chưa hiển thị cho người học. Hoàn thiện rồi gửi một lần xét duyệt mới.'):notice('Kết quả được giữ trong lịch sử. Mọi cập nhật tiếp theo tạo phiên bản mới.')}</section><aside class="panel"><h2>Lịch sử minh họa</h2><ol class="timeline"><li><strong>Tạo bản nháp</strong><small>09/10/2026 · ${esc(r.sender)}</small></li><li><strong>${s==='DRAFT'?'Lưu bản nháp':'Gửi công bố'}</strong><small>10/10/2026 · ${esc(r.sender)}</small></li>${s!=='SUBMITTED'&&s!=='DRAFT'?`<li><strong>${statusNames[s]||'Đã xử lý'}</strong><small>11/10/2026 · quyết định minh họa</small></li>`:''}</ol><p class="small section">Lịch sử trong màn hình này là mẫu bố cục, chưa phải nhật ký hệ thống thực.</p></aside></div>`;
}
function queue(){const pending=requests.filter(r=>r.status==='SUBMITTED');return heading('Hàng đợi kiểm duyệt','Kiểm tra nội dung, nguồn và quyền sử dụng trước khi công bố.')+`<div class="results-bar"><h2>${pending.length} lượt gửi chờ duyệt</h2><span>Ưu tiên kiểm tra từng phiên bản</span></div>`+(listState()||(pending.length?`<div class="table-wrap"><table><caption>Lượt gửi chờ duyệt</caption><thead><tr><th>Tài liệu / phiên bản</th><th>Người gửi</th><th>Trạng thái file</th><th>Thao tác</th></tr></thead><tbody>${pending.map(r=>{const d=docById(r.doc);return `<tr><td><strong>${esc(d.title)}</strong><small>${esc(d.course)} · Phiên bản ${r.version}</small><div class="row-tags">${badge(d.kind==='lecturer'?'Giảng viên':'Sinh viên bổ sung',d.kind==='student'?'warning':'')}</div></td><td>${esc(r.sender)}<small>Gửi 10/10/2026 · minh họa</small></td><td>${badge('SAFE · An toàn')}</td><td>${link('Kiểm duyệt',`review/${r.id}`,'secondary compact','arrow')}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Đã xử lý hết lượt gửi mẫu','Các quyết định mới sẽ xuất hiện ở người gửi và kho học liệu khi phù hợp.',link('Xem học liệu','management'),'check')));}
function review(id){const r=reqById(id),d=submittedDoc(r),fileBlocked=['checking','failed'].includes(state.scenario);return back('Về hàng đợi','queue')+heading('Kiểm duyệt tài liệu','Xét đúng phiên bản và lần gửi. Admin yêu cầu người gửi sửa nội dung khi cần.')+`<div class="detail-layout"><section class="panel"><div class="status-grid"><div><small>Công bố</small>${statusBadge(r.status)}</div><div><small>An toàn file</small>${badge(fileBlocked?(state.scenario==='checking'?'CHECKING':'FAILED'):'SAFE',fileBlocked?'warning':'')}</div><div><small>Hiển thị tài liệu</small>${badge(d.visibility==='HIDDEN'?'Đang ẩn':'Hiển thị',d.visibility==='HIDDEN'?'warning':'neutral')}</div></div><h2>${esc(d.title)}</h2><dl class="metadata"><dt>Phiên bản xét duyệt</dt><dd>${r.version}${d.published?` · Bản hiện hành: ${d.version}`:''}</dd><dt>Người gửi</dt><dd>${esc(r.sender)}</dd><dt>Tác giả hiển thị</dt><dd>${esc(d.author)}</dd><dt>Loại tài liệu</dt><dd>${d.kind==='lecturer'?'Giáo trình giảng viên':'Sinh viên bổ sung'}</dd><dt>Môn và phân công</dt><dd>${esc(d.course)}${d.kind==='lecturer'?' · Có phân công trong tình huống mẫu':''}</dd><dt>Nguồn</dt><dd>${esc(d.source)}</dd><dt>Căn cứ quyền</dt><dd>${esc(d.rights)}</dd><dt>Thay đổi</dt><dd>${esc(r.summary)}</dd><dt>File</dt><dd>${esc(r.file)}</dd></dl><div class="section">${btn('Xem trước file mẫu',`preview:${r.id}`,'secondary','eye').replace('<button ',`<button ${fileBlocked?'disabled ':''}`)}</div>${fileBlocked?notice('Chặn xem trước và ra quyết định công bố cho tới khi file kiểm tra an toàn.','warning'):notice('Xem trước là trang minh họa. Kiểm tra malware, nội dung và quyền nguồn thực cần triển khai riêng.')}</section><aside class="panel"><h2>Quyết định kiểm duyệt</h2><ul class="review-checklist"><li>${icon('check')}Đối chiếu tác giả, môn và phân công</li><li>${icon('check')}Kiểm tra nguồn và căn cứ quyền</li><li>${icon('check')}File an toàn, đúng bản gửi</li></ul>${r.status==='SUBMITTED'?`<div class="decision-actions">${btn('Duyệt công bố',`decision:APPROVED:${r.id}`,'','check').replace('<button ',`<button ${fileBlocked?'disabled ':''}`)}${btn('Yêu cầu sửa',`decision:CHANGES_REQUIRED:${r.id}`).replace('<button ',`<button ${fileBlocked?'disabled ':''}`)}${btn('Từ chối',`decision:REJECTED:${r.id}`).replace('<button ',`<button ${fileBlocked?'disabled ':''}`)}</div>`:notice('Lượt gửi đã xử lý. Không áp dụng quyết định lần thứ hai.')}<hr class="quiet-rule"><p class="small">Admin không chỉnh sửa file hoặc metadata nội dung thay người gửi. Bản mới của tài liệu đang ẩn không tự mở lại tài liệu.</p></aside></div>`;}
function accountScreen(){return heading('Tài khoản','Cấp và xác minh từ danh sách hợp lệ. MVP chưa có tự đăng ký.',btn('Cấp tài khoản','new-account','','plus'))+`<div class="table-wrap"><table><caption>Tài khoản minh họa</caption><thead><tr><th>Người dùng</th><th>Vai trò</th><th>Xác minh</th><th>Trạng thái / thao tác</th></tr></thead><tbody>${accounts.map((a,i)=>`<tr><td><strong>${esc(a.name)}</strong><small>${esc(a.email)}</small></td><td>${esc(a.role)}</td><td>${a.verified?badge('Đã xác minh'):btn('Xác minh',`verify:${i}`,'secondary compact')}</td><td>${badge(!a.active?'Đã khóa':a.verified?'Hoạt động':'Chờ xác minh',a.active&&a.verified?'':'warning')} <button class="text-button" data-action="toggle-account:${i}">${a.active?'Khóa':'Mở khóa'}</button></td></tr>`).join('')}</tbody></table></div>`+notice('Không khóa hoặc hạ quyền admin hoạt động cuối cùng. Xác minh và vai trò cần kiểm tra tại backend trong sản phẩm thật.');}
function coursesScreen(){return heading('Danh mục và phân công','Mã môn, khoa và người phụ trách dưới đây chỉ là dữ liệu thiết kế.',btn('Thêm phân công','new-assignment','','plus'))+`<section class="panel"><h2>Danh mục môn học mẫu</h2><div class="table-wrap"><table><caption>Môn học mẫu</caption><thead><tr><th>Môn học</th><th>Mã minh họa</th><th>Đơn vị quản lý mẫu</th></tr></thead><tbody>${courseNames.map((c,i)=>`<tr><td><strong>${esc(c)}</strong></td><td class="mono">MH-${String(i+1).padStart(3,'0')}</td><td>Đơn vị chuyên môn minh họa</td></tr>`).join('')}</tbody></table></div></section><section class="panel section"><h2>Phân công giảng viên</h2><div class="table-wrap"><table><caption>Phân công mẫu</caption><thead><tr><th>Giảng viên</th><th>Môn học</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${assignments.map((a,i)=>`<tr><td>${esc(a.name)}</td><td>${esc(a.course)}</td><td>${badge(a.active?'Đang phân công':'Đã thu hồi',a.active?'':'neutral')}</td><td>${a.active?btn('Thu hồi',`revoke:${i}`,'secondary compact'):'<span class="muted">Giữ lịch sử</span>'}</td></tr>`).join('')}</tbody></table></div>${notice('Thu hồi phân công chặn quyền quản lý tương ứng; không tự bàn giao hoặc gỡ bản đã công bố. Bản này minh họa quản lý phân công; CRUD đầy đủ khoa/ngành/môn được mô tả trong tài liệu bàn giao.')}</section>`;}
function management(){return heading('Học liệu và bàn giao','Quản lý hiển thị và người phụ trách, giữ nguyên nội dung đã công bố.')+`<div class="table-wrap"><table><caption>Quản lý học liệu</caption><thead><tr><th>Tài liệu</th><th>Người quản lý</th><th>Hiển thị</th><th>Thao tác</th></tr></thead><tbody>${documents.map(d=>`<tr><td><strong>${esc(d.title)}</strong><small>${esc(d.course)} · ${d.kind==='lecturer'?'Giáo trình':'Sinh viên bổ sung'}</small></td><td>${esc(d.manager)}</td><td>${badge(d.visibility==='HIDDEN'?'Đang ẩn':'Hiển thị',d.visibility==='HIDDEN'?'warning':'')}</td><td><div class="row-tags">${d.kind==='lecturer'?btn('Bàn giao',`transfer:${d.id}`,'secondary compact','transfer'):''}${btn(d.visibility==='HIDDEN'?'Khôi phục':'Ẩn tài liệu',`visibility:${d.id}`,'secondary compact')}</div></td></tr>`).join('')}</tbody></table></div>${transferHistory.length?`<section class="panel section"><h2>Bàn giao trong phiên xem thử</h2>${transferHistory.map(t=>`<p class="small">${esc(t)}</p>`).join('')}</section>`:''}`;}
function reportScreen(){return heading('Báo cáo nội dung','Xử lý phản ánh, ghi kết quả và quyết định hiển thị riêng khi cần.')+`<div class="table-wrap"><table><caption>Báo cáo minh họa</caption><thead><tr><th>Nội dung được báo cáo</th><th>Vấn đề</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${reports.map(r=>`<tr><td><strong>${esc(r.title)}</strong><small>${esc(r.description)}</small>${r.result?`<small>Kết quả: ${esc(r.result)}</small>`:''}</td><td>${esc(r.reason)}</td><td>${badge(r.status==='OPEN'?'Cần xử lý':'Đã xử lý',r.status==='OPEN'?'warning':'')}</td><td>${r.status==='OPEN'?btn('Xử lý',`resolve-report:${r.id}`,'secondary compact'):'<span class="muted">Đã ghi kết quả</span>'}</td></tr>`).join('')}</tbody></table></div>`;}
function bookAdmin(){return heading('Quản lý danh mục sách','Biên tập thông tin và liên kết nguồn được phép; không mặc định có toàn văn.',btn('Thêm bản ghi sách','edit-book:new','','plus'))+`<div class="table-wrap"><table><caption>Danh mục sách quản trị</caption><thead><tr><th>Sách</th><th>Nguồn</th><th>PDF nội bộ</th><th>Thao tác</th></tr></thead><tbody>${books.map(b=>`<tr><td><strong>${esc(b.title)}</strong><small>${esc(b.author)} · ${esc(b.year)}</small></td><td>Nguồn minh họa<small>URL cần kiểm tra khi triển khai</small></td><td>Chưa có</td><td>${btn('Sửa thông tin',`edit-book:${b.id}`,'secondary compact')}</td></tr>`).join('')}</tbody></table></div>`;}
function auth(reset=false){return `<div class="auth"><section class="auth-story">${brand()}<div><h1>Học liệu đúng chỗ.<br>Ghi chú đúng trang.</h1><p>Tìm tài liệu theo môn, đọc và giữ lại điều bạn cần nhớ trong một không gian học tập.</p></div><div class="auth-foot">Bản thiết kế HUCEScholar · Chưa phải hệ thống chính thức của trường</div></section><section class="auth-form" id="main" tabindex="-1"><div class="auth-box"><h1 tabindex="-1">${reset?'Khôi phục mật khẩu':'Chào bạn trở lại'}</h1><p>${reset?'Nhập email tài khoản được cấp. Phản hồi sẽ không tiết lộ email có tồn tại hay không.':'Sử dụng tài khoản đã được cấp và xác minh để truy cập học liệu.'}</p><form id="${reset?'reset-form':'login-form'}">${field('Email tài khoản','email','','Dùng email được quản trị viên cấp hoặc xác minh.','email',true)}${reset?'':field('Mật khẩu','password','','Trong prototype không cần nhập mật khẩu thật.','password',false)}<button class="button" type="submit">${reset?'Gửi yêu cầu khôi phục':'Vào không gian xem thử'}</button></form><div class="auth-links"><a href="#/${reset?'login':'reset'}">${reset?'Quay lại đăng nhập':'Quên mật khẩu?'}</a></div><div class="auth-note">Chưa có tài khoản? Liên hệ quản trị viên học liệu. Không có tự đăng ký trong MVP.<br><br>Bản thiết kế không xác thực hoặc gửi email. Chọn vai trò bằng thanh điều khiển phía trên.</div></div></section></div>`;}
function render(){
  const [screen,id,version]=route();
  const adminOnly=['queue','review','accounts','courses','management','reports','bookadmin'];
  const roleMismatch=(adminOnly.includes(screen)&&state.role!=='admin')||(screen==='materials'&&state.role!=='lecturer')||(screen==='contributions'&&state.role!=='student')||(['editor','submission'].includes(screen)&&state.role==='admin');
  if(roleMismatch){navigate(normalHome());return;}
  const scenarios=scenarioOptions(screen);if(!scenarios.some(s=>s[0]===state.scenario))state.scenario='normal';
  $('#scenario').innerHTML=scenarios.map(([key,label])=>`<option value="${key}" ${key===state.scenario?'selected':''}>${label}</option>`).join('');
  $('#scenario').disabled=scenarios.length===1;
  document.title=`${screenTitles[screen]||'Kho học liệu'} · HUCEScholar wireframe`;
  if(screen==='login'||screen==='reset'){$('#app').innerHTML=auth(screen==='reset');return;}
  const pages={catalog,detail:()=>detail(id),reader:()=>reader(id,version),library,books:bookCatalog,book:()=>bookDetail(id),contributions:materials,materials,editor:()=>editor(id||'new'),submission:()=>submission(id),queue,review:()=>review(id),accounts:accountScreen,courses:coursesScreen,management,reports:reportScreen,bookadmin:bookAdmin};
  const html=(pages[screen]||catalog)();
  $('#app').innerHTML=`<div class="app-shell">${navHTML(screen)}<div class="workspace"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Mở điều hướng" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb"><span>Không gian học liệu</span>${icon('chevron')}<span>${screenTitles[screen]||'Kho học liệu'}</span></div><div class="topbar-right"><span class="verified">${icon('shield')}<span>Tài khoản đã xác minh</span></span><span>${roleNames[state.role]}</span></div></header><main id="main" tabindex="-1" class="content ${screen==='reader'?'reader-content':''}">${html}<footer class="screen-reference"><span>${screenIds[screen]||'S01'} · Thiết kế v2 · Nội dung và tên người minh họa</span><span>Trạng thái thay đổi chỉ trong phiên xem thử</span></footer></main></div></div>`;
}
// Local interactions are intentionally explicit rather than pretending to call real services.
document.addEventListener('click',event=>{
  const target=event.target.closest('[data-action]');if(!target)return;
  const [action,a,b]=target.dataset.action.split(':');
  if(action==='close-dialog'){closeDialog();return;}
  if(action==='focus-notes'){$('#notes-heading').scrollIntoView({block:'start'});$('#notes-heading').focus({preventScroll:true});return;}
  if(action==='menu'){const open=$('#sidebar').classList.toggle('open');$('.topbar .mobile-menu')?.setAttribute('aria-expanded',String(open));if(!open)$('.topbar .mobile-menu')?.focus();return;}
  if(action==='retry'){state.scenario='normal';render();return;}
  if(action==='clear-filters'){state.query='';state.course='';state.source='';state.scenario='normal';render();return;}
  if(action==='save'){const id=Number(a);if(saved[state.role].has(id))saved[state.role].delete(id);else saved[state.role].add(id);render();toast(saved[state.role].has(id)?'Đã lưu tài liệu vào thư viện trong phiên xem thử.':'Đã bỏ lưu; ghi chú và tiến độ vẫn được giữ.');return;}
  if(action==='unsave'){dialog('Bỏ lưu tài liệu?',`<p>${esc(docById(a).title)}</p><p>Bỏ tài liệu khỏi mục đã lưu. Ghi chú riêng và tiến độ đọc vẫn được giữ.</p>`,btn('Giữ tài liệu','close-dialog')+btn('Bỏ lưu',`confirm-unsave:${a}`,''));return;}
  if(action==='confirm-unsave'){saved[state.role].delete(Number(a));closeDialog();render();toast('Đã bỏ lưu. Ghi chú và tiến độ không bị xóa.');return;}
  if(action==='download'||action==='book-source'){dialog(action==='download'?'Tải file gốc — mô phỏng':'Mở nguồn sách — mô phỏng',`<p>${action==='download'?'Sản phẩm thật sẽ kiểm tra lại quyền và cấp file PDF gốc, không kèm ghi chú.':'Sản phẩm thật sẽ mở URL nguồn đã kiểm tra. Quyền đọc phụ thuộc đơn vị nguồn.'}</p><p>Bản thiết kế không tải file hoặc mở một nguồn sách giả. ${action==='download'?'Quyền tải được thể hiện bằng trạng thái nút và thông tin tài liệu.':'Chưa có dữ liệu sách trường được tích hợp.'}</p>`,btn('Đã hiểu','close-dialog',''));return;}
  if(action==='page'||action==='prev-page'||action==='next-page'){state.page=action==='page'?Number(a):state.page+(action==='prev-page'?-1:1);progress[state.role][`${state.activeId}/${state.readerVersion}`]=state.page;render();return;}
  if(action==='delete-note'){dialog('Xóa ghi chú này?',`<p>Chỉ xóa ghi chú bạn chọn. File tài liệu và những ghi chú khác không thay đổi.</p>`,btn('Giữ ghi chú','close-dialog')+btn('Xóa ghi chú',`confirm-delete-note:${a}`,'danger'));return;}
  if(action==='confirm-delete-note'){const i=notes.findIndex(n=>n.id===Number(a)&&n.role===state.role);if(i>=0)notes.splice(i,1);closeDialog();render();toast('Đã xóa ghi chú trong phiên xem thử.');return;}
  if(action==='library-tab'){state.libraryTab=a;render();return;}
  if(action==='report'||action==='report-book'){const isBook=action==='report-book',d=isBook?books.find(x=>x.id===Number(a)):docById(a);dialog('Báo cáo vấn đề',`<form id="report-form" data-target="${isBook?'book':'doc'}" data-id="${a}"><p>${esc(d.title)}</p><div class="field"><label for="report-kind">Loại vấn đề</label><select id="report-kind" name="kind">${options(['Nội dung cần đính chính','Nguồn / quyền sử dụng','Liên kết hoặc file lỗi','Thông tin tài liệu sai'])}</select></div>${textarea('Mô tả vấn đề','report-description','','Không gửi mật khẩu, thông tin nhạy cảm hoặc nội dung ghi chú riêng.',true)}<div class="form-actions"><button type="button" class="button secondary" data-action="close-dialog">Hủy</button><button class="button" type="submit">Gửi báo cáo</button></div></form>`);return;}
  if(action==='withdraw'){dialog('Rút bản về nháp?',`<p>Phiên bản ${reqById(a).version} sẽ ngừng chờ duyệt. Bạn có thể chỉnh sửa rồi gửi một lượt mới. Bản đang công bố vẫn được giữ.</p>${textarea('Lý do rút','withdraw-reason','','Bắt buộc ghi lý do để giữ lịch sử.',true)}`,btn('Tiếp tục chờ','close-dialog')+btn('Rút về nháp',`confirm-withdraw:${a}`,''));return;}
  if(action==='confirm-withdraw'){if(!$('#withdraw-reason').reportValidity())return;const r=reqById(a);r.reason=$('#withdraw-reason').value;r.status='DRAFT';closeDialog();render();toast('Đã rút về nháp; lần gửi trước được giữ trong lịch sử sản phẩm thật.');return;}
  if(action==='new-version'){const old=reqById(a),working=requests.find(r=>r.doc===old.doc&&['DRAFT','SUBMITTED','CHANGES_REQUIRED'].includes(r.status));if(working){navigate(`submission/${working.id}`);toast('Tài liệu đã có một phiên bản đang làm.');return;}const next={...old,id:Date.now(),version:Math.max(docById(old.doc).version,...requests.filter(r=>r.doc===old.doc).map(r=>r.version))+1,status:'DRAFT',reason:'',summary:''};requests.push(next);state.editorDraft=null;navigate(`editor/${next.id}`);return;}
  if(action==='preview'){const r=reqById(a);dialog('Xem trước file — minh họa',`<p><strong>${esc(docById(r.doc).title)}</strong><br>Phiên bản ${r.version} · ${esc(r.file)}</p><div class="panel"><h3>Trang nội dung minh họa</h3><p>Trong sản phẩm thật, reader kiểm duyệt hiển thị file PDF an toàn của chính lần gửi này. Không hiển thị ghi chú cá nhân của người gửi hoặc sinh viên.</p></div>`,btn('Đóng xem trước','close-dialog',''));return;}
  if(action==='decision'){const r=reqById(b),approved=a==='APPROVED';dialog(approved?'Duyệt công bố phiên bản?':a==='REJECTED'?'Từ chối phiên bản?':'Yêu cầu người gửi chỉnh sửa',`<p><strong>${esc(docById(r.doc).title)}</strong> · Phiên bản ${r.version}</p>${approved?'<p>Phiên bản này sẽ trở thành bản hiện hành. Bản đã duyệt trước và ghi chú của người học được giữ. Tài liệu đang ẩn vẫn tiếp tục ẩn.</p>':textarea('Lý do / nội dung cần sửa','decision-reason','','Người gửi sẽ thấy nội dung này.',true)}`,btn('Hủy','close-dialog')+btn(approved?'Duyệt công bố':a==='REJECTED'?'Xác nhận từ chối':'Gửi yêu cầu sửa',`confirm-decision:${a}:${b}`,a==='REJECTED'?'danger':''));return;}
  if(action==='confirm-decision'){const r=reqById(b);if(r.status!=='SUBMITTED'){closeDialog();render();return;}if(a!=='APPROVED'&&!$('#decision-reason').reportValidity())return;r.status=a;r.reason=$('#decision-reason')?.value||'';if(a==='APPROVED'){const d=docById(r.doc);d.published=true;d.version=r.version;if(r.draft){d.title=r.draft.title;d.author=r.draft.authors;d.course=r.draft.course;d.description=r.draft.description;d.download=r.draft.download;}}closeDialog();render();toast(`Đã ${a==='APPROVED'?'duyệt công bố':a==='REJECTED'?'từ chối':'gửi yêu cầu sửa'} trong phiên xem thử.`);return;}
  if(action==='new-account'){dialog('Cấp tài khoản',`<form id="account-form">${field('Tên hiển thị','account-name','','','text',true)}${field('Email','account-email','','Chỉ dùng email minh họa khi bấm thử.','email',true)}<div class="field"><label for="account-role">Vai trò</label><select id="account-role" name="role">${options(['Sinh viên','Giảng viên','Quản trị'])}</select></div><p class="small">Tài khoản mới chờ xác minh danh sách hợp lệ. Prototype không gửi email hoặc tạo mật khẩu thật.</p><div class="form-actions"><button type="button" class="button secondary" data-action="close-dialog">Hủy</button><button class="button" type="submit">Cấp tài khoản mẫu</button></div></form>`);return;}
  if(action==='verify'){accounts[Number(a)].verified=true;render();toast('Đã xác minh tài khoản mẫu.');return;}
  if(action==='toggle-account'){const account=accounts[Number(a)];if(account.active&&account.role==='Quản trị'&&accounts.filter(x=>x.role==='Quản trị'&&x.active).length===1){dialog('Cần giữ một admin hoạt động','<p>Không thể khóa admin hoạt động cuối cùng. Hãy có một admin khác được xác minh và hoạt động trước khi thực hiện.</p>',btn('Đã hiểu','close-dialog',''));return;}dialog(account.active?'Khóa tài khoản?':'Mở khóa tài khoản?',`<p>${esc(account.name)} · ${esc(account.email)}</p><p>${account.active?'Ngừng truy cập và thu hồi phiên trong sản phẩm thật. Dữ liệu nội dung/ghi chú vẫn được giữ.':'Tài khoản vẫn cần được xác minh trước khi dùng học liệu.'}</p>`,btn('Hủy','close-dialog')+btn('Xác nhận',`confirm-account:${a}`,''));return;}
  if(action==='confirm-account'){accounts[Number(a)].active=!accounts[Number(a)].active;closeDialog();render();return;}
  if(action==='new-assignment'){dialog('Thêm phân công',`<form id="assignment-form"><div class="field"><label for="assignment-person">Giảng viên</label><select id="assignment-person" name="person">${options(['Nguyễn Minh An','Lê Thu Hà'])}</select></div><div class="field"><label for="assignment-course">Môn học</label><select id="assignment-course" name="course">${options(courseNames)}</select></div><div class="form-actions"><button type="button" class="button secondary" data-action="close-dialog">Hủy</button><button class="button" type="submit">Lưu phân công</button></div></form>`);return;}
  if(action==='revoke'){dialog('Thu hồi phân công?',`<p>${esc(assignments[Number(a)].name)} · ${esc(assignments[Number(a)].course)}</p><p>Chặn sửa/gửi mới trong phạm vi này. Không tự đổi chủ quản lý, xóa file hoặc ẩn bản công bố.</p>${textarea('Lý do thu hồi','revoke-reason','','',true)}`,btn('Hủy','close-dialog')+btn('Thu hồi phân công',`confirm-revoke:${a}`,'danger'));return;}
  if(action==='confirm-revoke'){if(!$('#revoke-reason').reportValidity())return;assignments[Number(a)].active=false;closeDialog();render();toast('Đã thu hồi phân công mẫu, giữ lịch sử.');return;}
  if(action==='transfer'){const d=docById(a),eligible=['Nguyễn Minh An','Lê Thu Hà'].filter(name=>name!==d.manager&&assignments.some(x=>x.name===name&&x.course===d.course&&x.active));dialog('Bàn giao người quản lý',`<p><strong>${esc(d.title)}</strong></p><dl class="metadata"><dt>Người quản lý cũ</dt><dd>${esc(d.manager)}</dd><dt>Môn liên quan</dt><dd>${esc(d.course)}</dd></dl><div class="field"><label for="transfer-person">Giảng viên nhận *</label><select id="transfer-person" required><option value="">Chọn người nhận đủ phân công</option>${options(eligible)}</select><small>${eligible.length?'Chỉ hiển thị người nhận phù hợp trong dữ liệu mẫu.':'Chưa có người nhận đủ điều kiện; cần phân công trước.'}</small></div>${textarea('Lý do bàn giao','transfer-reason','','',true)}${notice('Bản đang chờ duyệt sẽ bị rút về nháp. Người nhận rà soát rồi gửi lại. Giữ bản công bố, tác giả, lịch sử và ghi chú.','warning')}`,btn('Hủy','close-dialog')+btn('Xác nhận bàn giao',`confirm-transfer:${a}`,'').replace('<button ',`<button ${eligible.length?'':'disabled '}`));return;}
  if(action==='confirm-transfer'){if(!$('#transfer-person').reportValidity()||!$('#transfer-reason').reportValidity())return;const d=docById(a),old=d.manager;d.manager=$('#transfer-person').value;requests.filter(r=>r.doc===d.id&&r.status==='SUBMITTED').forEach(r=>{r.status='DRAFT';r.reason='Rút do bàn giao người quản lý';});transferHistory.push(`${d.title}: ${old} → ${d.manager}. Lý do: ${$('#transfer-reason').value}`);closeDialog();render();toast('Đã bàn giao mẫu, rút bản chờ về nháp và giữ bản công bố.');return;}
  if(action==='visibility'){const d=docById(a),restore=d.visibility==='HIDDEN';dialog(restore?'Khôi phục học liệu?':'Ẩn toàn bộ học liệu?',`<p><strong>${esc(d.title)}</strong></p><p>${restore?'Chỉ khôi phục khi bản hiện hành đã duyệt, an toàn và quyền nguồn hợp lệ. Bản cũ kiểm tra riêng.':'Mọi phiên bản ngừng cấp lượt đọc/tải mới. Ghi chú và mục lưu giữ nguyên; file đã tải không thể thu hồi.'}</p>${textarea('Lý do','visibility-reason','','',true)}`,btn('Hủy','close-dialog')+btn(restore?'Khôi phục':'Ẩn tài liệu',`confirm-visibility:${a}`,restore?'':'danger'));return;}
  if(action==='confirm-visibility'){if(!$('#visibility-reason').reportValidity())return;const d=docById(a);if(d.visibility==='HIDDEN'&&!d.published){toast('Cần có bản công bố hợp lệ trước khi khôi phục.');return;}d.visibility=d.visibility==='HIDDEN'?'VISIBLE':'HIDDEN';closeDialog();render();return;}
  if(action==='resolve-report'){const r=reports.find(x=>x.id===Number(a));dialog('Xử lý báo cáo',`<form id="resolve-form" data-id="${a}"><p><strong>${esc(r.title)}</strong></p><p>${esc(r.description)}</p>${textarea('Kết quả trả lời người báo cáo','report-result','','Không chứa thông tin riêng tư của người khác.',true)}<p class="small">Đóng báo cáo không tự ẩn học liệu. Nếu cần gỡ, dùng “Học liệu & bàn giao” và nhập lý do riêng.</p><div class="form-actions"><button type="button" class="button secondary" data-action="close-dialog">Hủy</button><button class="button" type="submit">Ghi kết quả và đóng</button></div></form>`);return;}
  if(action==='edit-book'){const item=books.find(x=>x.id===Number(a));dialog(item?'Sửa thông tin sách':'Thêm bản ghi sách',`<form id="book-form" data-id="${a}">${field('Tên sách','book-title',item?.title||'','','text',true)}${field('Tác giả','book-authors',item?.author||'','','text',true)}${field('URL nguồn','book-url','https://example.org/catalog/demo','Địa chỉ ví dụ, không phải nguồn sách thực.','url',true)}${textarea('Căn cứ sử dụng metadata','book-rights','Căn cứ minh họa cho thiết kế.','Cần kiểm tra thực tế trước nhập dữ liệu trường.',true)}<div class="form-actions"><button type="button" class="button secondary" data-action="close-dialog">Hủy</button><button class="button" type="submit">Lưu thông tin mẫu</button></div></form>`);return;}
});
document.addEventListener('submit',event=>{
  const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();
  const data=new FormData(form);
  if(form.id==='search-form'){state.query=data.get('query').trim();state.scenario='normal';render();return;}
  if(form.id==='note-form'){
    if(!form.reportValidity())return;state.noteDraft=data.get('note').trim();
    if(!state.noteDraft){$('#note-content').setCustomValidity('Nhập nội dung ghi chú.');$('#note-content').reportValidity();return;}
    if(state.scenario==='noteerror'&&state.saveState!=='failed'){state.saveState='failed';render();return;}
    notes.push({id:Date.now(),doc:state.activeId,version:state.readerVersion,role:state.role,page:state.page,content:state.noteDraft,quote:''});state.noteDraft='';state.saveState='saved';state.scenario='normal';progress[state.role][`${state.activeId}/${state.readerVersion}`]=state.page;render();toast('Đã lưu ghi chú trong phiên xem thử.');return;
  }
  if(form.id==='editor-form'){
    const intent=event.submitter?.value||'draft',existing=form.dataset.request?reqById(form.dataset.request):null;
    const file=$('#pdf-file').files[0];
    state.editorDraft={title:String(data.get('title')).trim(),authors:String(data.get('authors')).trim(),course:data.get('course'),description:String(data.get('description')).trim(),source:String(data.get('source')).trim(),rights:String(data.get('rights')).trim(),summary:data.get('summary')||'',download:data.has('download')};
    const errors=[];if(!state.editorDraft.title)errors.push('Nhập tên tài liệu.');
    if(intent==='submit'){
      if(!state.editorDraft.authors)errors.push('Nhập tác giả / người biên soạn.');if(!state.editorDraft.course)errors.push('Chọn môn học.');if(!state.editorDraft.description)errors.push('Mô tả nội dung tài liệu.');if(!state.editorDraft.source)errors.push('Bổ sung nguồn hoặc tài liệu tham chiếu.');if(!state.editorDraft.rights)errors.push('Bổ sung căn cứ cho phép chia sẻ.');if(!file&&!existing?.fileSelected)errors.push('Chọn file PDF trước khi gửi.');if(['checking','failed'].includes(state.scenario))errors.push('File chưa đủ điều kiện an toàn.');
    }
    if(file&&!/\.pdf$/i.test(file.name))errors.push('Chọn file có đuôi .pdf. Sản phẩm thật cần kiểm tra nội dung bytes.');
    if(errors.length){$('#form-errors').innerHTML=`<div class="inline-notice error" role="alert" tabindex="-1"><div><strong>Chưa thể ${intent==='submit'?'gửi công bố':'lưu nháp'}</strong><ul>${errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div></div>`;$('#form-errors [role=alert]').focus();return;}
    let d=existing?docById(existing.doc):null;
    if(!d){d={id:Date.now(),title:state.editorDraft.title,course:state.editorDraft.course||courseNames[0],author:state.editorDraft.authors||people[state.role][1],kind:state.role==='lecturer'?'lecturer':'student',version:1,published:false,download:state.editorDraft.download,pages:3,manager:people[state.role][1],visibility:'VISIBLE',description:state.editorDraft.description};documents.push(d);}
    // Draft metadata stays on the request, leaving approved metadata untouched in this mock model.
    let r=existing;if(!r){r={id:Date.now()+1,doc:d.id,version:1,sender:people[state.role][1],role:state.role,reason:'',file:file?.name||'',fileSelected:!!file};requests.push(r);}
    r.summary=state.editorDraft.summary||'Nội dung minh họa mới';r.draft={...state.editorDraft};r.file=file?.name||r.file;r.fileSelected=!!file||r.fileSelected===true;r.status=intent==='submit'?'SUBMITTED':'DRAFT';state.editorDraft=null;navigate(`submission/${r.id}`);toast(intent==='submit'?'Đã gửi công bố trong mô phỏng; chưa có upload hoặc kiểm tra file thật.':'Đã lưu nháp trong phiên xem thử.');return;
  }
  if(form.id==='login-form'){if(!form.reportValidity())return;navigate(normalHome());toast('Đang xem không gian mẫu. Không có xác thực thật.');return;}
  if(form.id==='reset-form'){if(!form.reportValidity())return;dialog('Đã tiếp nhận yêu cầu — mô phỏng','<p>Nếu email thuộc tài khoản hợp lệ, hệ thống thật sẽ gửi hướng dẫn khôi phục. Prototype không gửi email.</p>',btn('Về đăng nhập','close-dialog',''));return;}
  if(!form.reportValidity())return;
  if(form.id==='report-form'){const isBook=form.dataset.target==='book',d=isBook?books.find(x=>x.id===Number(form.dataset.id)):docById(form.dataset.id);reports.push({id:Date.now(),title:d.title,doc:isBook?null:d.id,reason:data.get('kind'),description:data.get('report-description'),status:'OPEN',result:''});closeDialog();toast('Đã ghi báo cáo trong phiên xem thử.');return;}
  if(form.id==='account-form'){const email=String(data.get('account-email')).trim().toLowerCase();if(accounts.some(x=>x.email===email)){toast('Email đã tồn tại trong dữ liệu mẫu.');return;}accounts.push({name:data.get('account-name'),email,role:data.get('role'),active:true,verified:false});closeDialog();render();toast('Đã tạo tài khoản mẫu chờ xác minh.');return;}
  if(form.id==='assignment-form'){if(assignments.some(x=>x.name===data.get('person')&&x.course===data.get('course')&&x.active)){toast('Phân công này đã tồn tại.');return;}assignments.push({name:data.get('person'),course:data.get('course'),active:true});closeDialog();render();return;}
  if(form.id==='resolve-form'){const r=reports.find(x=>x.id===Number(form.dataset.id));r.status='RESOLVED';r.result=data.get('report-result');closeDialog();render();return;}
  if(form.id==='book-form'){let book=books.find(x=>x.id===Number(form.dataset.id));if(!book){book={id:Date.now(),year:'2026',edition:'Bản ghi mẫu',cover:'Sách\nminh họa',course:courseNames[0]};books.push(book);}book.title=data.get('book-title');book.author=data.get('book-authors');closeDialog();render();toast('Đã lưu metadata sách trong phiên xem thử.');}
});
document.addEventListener('input',event=>{
  if(event.target.id==='note-content'){state.noteDraft=event.target.value;state.saveState='dirty';event.target.setCustomValidity('');$('#save-indicator').textContent='Có thay đổi chưa lưu.';$('#save-indicator').classList.remove('error');}
});
document.addEventListener('change',event=>{
  const t=event.target;
  if(t.id==='role'){setRole(t.value);return;}
  if(t.id==='scenario'){state.scenario=t.value;state.saveState='idle';render();return;}
  if(t.id==='filter-course'){state.course=t.value;render();return;}
  if(t.id==='filter-source'){state.source=t.value;render();return;}
  if(t.id==='page-number'){state.page=Math.max(1,Math.min(docById(state.activeId).pages,Number(t.value)||1));progress[state.role][`${state.activeId}/${state.readerVersion}`]=state.page;render();return;}
  if(t.id==='zoom'){state.zoom=Number(t.value);render();return;}
  if(t.id==='pdf-file'){$('#file-label').textContent=t.files[0]?`${t.files[0].name} · chỉ đọc tên trong prototype, chưa upload`:'Chưa chọn file';}
});
